import fs from'node:fs';import{validatePaperMigration}from'../live-paper/paper-migration-guard.mjs';
const inventory=JSON.parse(fs.readFileSync('data/paper-migration-inventory-20261006.json'));
const input={observedAt:inventory.observedAt,now:Date.parse(inventory.observedAt),current:inventory.current,proposed:inventory.current.map(r=>({cohort:r.cohort,originalBankHash:r.bankHash,originalBankMode:r.bankMode,originalAnchors:r.anchors,authoritativeOwner:r.authoritativeOwner,overlayHash:r.overlayHash,baseActorEnabled:r.authoritativeOwner!=='operator_overlay',status:r.status,accounting:r.accounting,nativeReplayVerified:false,originalSourceReplayVerified:false}))};
let rejectedUnproven=false;try{validatePaperMigration(input);}catch(e){if(!String(e).includes('NATIVE_REPLAY_UNPROVEN'))throw e;rejectedUnproven=true;}
// Deliberately malformed test candidates; setting these flags supplies no
// actual native proof and can never activate a runtime.
const wrong=structuredClone(input);for(const r of wrong.proposed){r.nativeReplayVerified=true;r.originalSourceReplayVerified=true;}const tx=wrong.proposed.find(r=>r.authoritativeOwner==='operator_overlay');if(!tx)throw Error('Missing actual overlay');tx.authoritativeOwner='original_reducer';tx.baseActorEnabled=true;
let rejectedResurrection=false;try{validatePaperMigration(wrong);}catch(e){if(!String(e).includes('FENCED_BASE_RESURRECTION'))throw e;rejectedResurrection=true;}
if(!rejectedUnproven||!rejectedResurrection)throw Error('Actual inventory rejection check failed');
const out={schemaVersion:1,at:new Date().toISOString(),inventoryObservedAt:inventory.observedAt,currentReducers:inventory.current.length,rejectedUnprovenNativeImport:true,rejectedHistoricalBaseResurrection:true,actualOverlayCash:inventory.current.find(r=>r.authoritativeOwner==='operator_overlay').accounting.wallets['1000'].cash,actualOverlayRealizedPnl:inventory.current.find(r=>r.authoritativeOwner==='operator_overlay').accounting.wallets['1000'].realizedPnl,nativeImportProven:false,cutoverReady:false,runtimeChanges:0,accountRequests:0,competitionOrders:0};fs.writeFileSync('data/paper-migration-rejection-proof-20261006.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify(out));
